(function() {
  'use strict';

  // Ad blocking patterns
  const AD_DOMAINS = [
    'ads.google.com',
    'pagead2.googlesyndication.com',
    'googleadservices.com',
    'doubleclick.net',
    'ads.yahoo.com',
    'ads.facebook.com',
    'amazon-adsystem.com',
    'adn.ebscohost.com',
    'advertising.com',
    'atdmt.com',
    'adserver.com',
    'ads.msn.com',
    'ads-bid.twitter.com',
    'ads.linkedin.com'
  ];

  const AD_SELECTORS = [
    'iframe[src*="ads"]',
    'iframe[src*="google"]',
    'div[data-ad-format]',
    'div[id*="google_ads"]',
    'div[id*="ad"][id*="\_"]',
    'ins.adsbygoogle',
    '.advertisement',
    '.ads',
    '.ad-banner',
    '[class*="ad-"]',
    '[class*="advert"]',
    'a[href*="ads."]',
    'a[href*="ad?"]'
  ];

  function blockElements() {
    // Block script tags loading from ad domains
    const scripts = document.querySelectorAll('script[src]');
    scripts.forEach(script => {
      const src = script.src || '';
      if (AD_DOMAINS.some(domain => src.includes(domain))) {
        script.remove();
      }
    });

    // Block iframes from ad domains
    const iframes = document.querySelectorAll('iframe[src]');
    iframes.forEach(iframe => {
      const src = iframe.src || '';
      if (AD_DOMAINS.some(domain => src.includes(domain))) {
        iframe.style.display = 'none';
        iframe.style.visibility = 'hidden';
        iframe.style.height = '0';
      }
    });

    // Block ad elements by selector
    AD_SELECTORS.forEach(selector => {
      try {
        document.querySelectorAll(selector).forEach(el => {
          el.style.display = 'none !important';
          el.style.visibility = 'hidden !important';
        });
      } catch (e) {}
    });
  }

  // Block on load
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', blockElements);
  } else {
    blockElements();
  }

  // Block dynamically added ads
  const observer = new MutationObserver(blockElements);
  observer.observe(document.body, { childList: true, subtree: true });

  // Log to console
  console.log('[SafeNet Ad Blocker] Active and blocking ads');
})();
